def equals_order_sensitive(self, other: object) -> bool:
    """Order-sensitive equality check.

    *See also* :ref:`eq-order-insensitive`
    (https://bidict.rtfd.io/other-bidict-types.html#eq-is-order-insensitive)
    """
    if not isinstance(other, Mapping):
        return False
    if not self:
        return True
    # Normalize other to a dict view and compare
    other_items = dict(other.items())
    # Check if we have the same items in the same order
    return self.items() == other_items.items()

@staticmethod
def _sort_key(item):
    """Return sort key for a (key, val) tuple.

    For hashable keys, sort by key. For unhashable keys, sort by key identity, then value.
    """
    key, val = item
    if isinstance(key, (int, str, float)):
        return (key, val)
    return (id(key), val)

def int_str(segment: PathSegment) -> PathSegment:
    """
    If the segment is an integer, return the string conversion.
    Otherwise return the segment unchanged. The conversion uses 'str'.

    int_str(segment) -> str
    """
    if isinstance(segment, int):
        return str(segment)
    return segment

