def iternodes(self, *, reverse: bool = False) -> Iterator[Node]:
    """Iterator yielding nodes in the requested order."""
    curr = self.prv() if reverse else self.nxt()
    while curr is not self:
        yield curr
        curr = (curr.prv() if reverse else curr.nxt())

