def leafy(thing):
    """
    Same as leaf(thing), but also treats empty sequences and
    dictionaries as True.
    """
    # Check if it's already a leaf (byte, str, int, float, bool, None)
    if isinstance(thing, (bytes, str, int, float, bool, type(None))):
        return True

    # Check if it's an empty sequence
    if isinstance(thing, Sequence):
        try:
            if len(thing) == 0:
                return True
        except TypeError:
            pass

    # Check if it's a dictionary
    if isinstance(thing, MutableMapping):
        try:
            if len(thing) == 0:
                return True
        except TypeError:
            pass

    return False

def get(obj, segments: Path):
    """
    Return the value at the path indicated by segments.

    get(obj, segments) -> value
    """
    # If segments is a single segment (or leaf), return the value
    if segments is None or not isinstance(segments, Sequence):
        return obj if not leafy(obj) else None

    current = obj
    for segment in segments:
        # Convert string segments to int if in a sequence
        if isinstance(current, Sequence) and isinstance(segment, str) and segment.isdecimal():
            segment = int(segment)

        # Normalize list indices
        if isinstance(current, MutableSequence):
            try:
                current = current[segment]
            except IndexError:
                raise PathNotFound(f"Path segment {segment} not found at '{current}'")
        elif isinstance(current, MutableMapping):
            try:
                current = current[segment]
            except KeyError:
                raise PathNotFound(f"Path segment {segment!r} not found at {current!r}")
        else:
            # Not a dict or sequence - treat as empty path
            return None

    # Return the value at the leaf if path exists
    if leaf(current):
        return current
    elif leafy(current):
        # For empty dicts/lists, treat as non-leaf
        return None
    else:
        # Intermediate node, return as-is
        return current

def make_walkable(node) -> Iterator[Tuple[PathSegment, Any]]:
    """
    Returns an iterator which yields tuple pairs of (node index, node value), regardless of node type.

    * For dict nodes `node.items()` will be returned.
    * For sequence nodes (lists/tuples/etc.) a zip between index number and index value will be returned.
    * Edge cases will result in an empty iterator being returned.

    make_walkable(node) -> (generator -> (key, value))
    """
    try:
        if len(node) == 0:
            return
        if isinstance(node, Sequence) and not isinstance(node, (bytes, bytearray)):
            # For sequences (lists, tuples, etc.), yield (index, value) pairs
            for i in range(len(node)):
                yield i, node[i]
        else:
            # For dicts, yield (key, value) pairs
            for k, v in node.items():
                yield k, v
    except TypeError:
        # Edge case: things without len() or items()
        return

def get(
        obj: MutableMapping,
        glob: Glob,
        separator=",/", 
        default: Any = _DEFAULT_SENTINEL
) -> Union[MutableMapping, object, Callable]:
    """
    Given an object which contains only one possible match for the given glob,
    return the value for the leaf matching the given glob.
    If the glob is not found and a default is provided,
    the default is returned.

    If more than one leaf matches the glob, ValueError is raised. If the glob is
    not found and a default is not provided, KeyError is raised.
    """
    split_segments = _split_path(glob, separator)

    if not split_segments:
        return obj

    all_values = []

    def walk(current_obj, path_segments):
        if segments.leaf(current_obj):
            matched = segments.match(path_segments, split_segments)
            if matched:
                all_values.append((path_segments, current_obj))
        else:
            if isinstance(current_obj, MutableMapping):
                for key, value in current_obj.items():
                    walk(value, path_segments + (key,))
            elif isinstance(current_obj, (list, tuple)):
                for i, value in enumerate(current_obj):
                    walk(value, path_segments + ((i),))

    walk(obj, ())

    results = []
    for segments, value in all_values:
        if segments.match(split_segments):
            results.append(value)

    if len(results) == 0:
        if default is not _DEFAULT_SENTINEL:
            return default
        raise KeyError(glob)
    elif len(results) == 1:
        return results[0]
    else:
        raise ValueError(f"Multiple names match: {glob}")

def slice(self, *args):
    """Returns a new :class:`Iter()` spec which trims iterables in the
    same manner as :func:`itertools.islice`.

    >>> target = [0, 1, 2, 3, 4, 5]
    >>> glom(target, Iter().slice(3).all())
    [0, 1, 2]
    >>> glom(target, Iter().slice(2, 4).all())
    [2, 3]

    This method accepts only positional arguments.
    """
    if len(args) == 1:
        return self._add_op('slice', (args[0],), lambda it, scope: islice(it, args[0]))
    elif len(args) == 2:
        return self._add_op('slice', (args[0], args[1]), lambda it, scope: islice(it, args[0], args[1]))
    elif len(args) == 3:
        return self._add_op('slice', (args[0], args[1], args[2]), lambda it, scope: islice(it, args[0], args[1], args[2]))
    else:
        raise TypeError("slice() takes at most 3 arguments (got {})".format(len(args)))

