def glomit(self, target, scope):
    if self.key not in target:
        if self.default is _MISSING:
            raise MatchError("target missing expected key %r", self.key)
        return arg_val(target, self.default, scope)
    return scope[glom](target, self.spec, scope)

def arg_val(target, arg, scope):
    """
    evaluate an argument to find its value
    (arg_val phonetically similar to "eval" -- evaluate as an arg)
    """
    # If arg is callable (has a glomit method), evaluate it
    # Otherwise, check if it's a container type and evaluate its contents
    glomit = getattr(arg, 'glomit', None)
    if callable(glomit):
        return glomit(target, scope)
    # Check for container types that need recursive evaluation
    if isinstance(arg, (list, tuple, dict)):
        if isinstance(arg, (list, tuple)):
            # evaluate all custom objects in the list
            result = [arg_val(target, item, scope) for item in arg]
            return type(arg)(result)
        elif isinstance(arg, dict):
            # evaluate all values in the dict
            return {k: arg_val(target, v, scope) for k, v in arg.items()}
    # Return the value as-is (it's a literal)
    return arg

