def always_reversible(iterable):
    """An extension of :func:`reversed` that supports all iterables, not
    just those which implement the ``Reversible`` or ``Sequence`` protocols.

        >>> print(*always_reversible(x for x in range(3)))
        2 1 0

    If the iterable is already reversible, this function returns the
    result of :func:`reversed()`. If the iterable is not reversible,
    this function will cache the remaining items in the iterable and
    yield them in reverse order, which may require significant storage.
    """
    from collections.abc import Sequence
    try:
        return reversed(iterable)
    except TypeError:
        return reversed(tuple(iterable))

def takewhile_inclusive(predicate, iterable):
    """A variant of :func:`takewhile` that yields one additional element.

        >>> list(takewhile_inclusive(lambda x: x < 5, [1, 4, 6, 4, 1]))
        [1, 4, 6]

    :func:`takewhile` would return ``[1, 4]``.
    """
    try:
        for item in iterable:
            if predicate(item):
                yield item
            else:
                yield item
                break
    except StopIteration:
        pass

def tail(n, iterable):
    """Return an iterator over the last *n* items of *iterable*.

    >>> t = tail(3, 'ABCDEFG')
    >>> list(t)
    ['E', 'F', 'G']

    """
    if n < 0:
        raise ValueError("n must be non-negative")

    # Check if iterable has a length
    try:
        iterable_len = len(iterable)
    except TypeError:
        iterable_len = None

    if iterable_len is not None:
        # Sized iterable: calculate start position and use islice
        start = max(0, iterable_len - n)
        return islice(iterable, start, None)
    else:
        # Unsized iterable: convert to list, then slice
        items = []
        for item in iterable:
            items.append(item)
        if n >= len(items):
            return iter(items)
        else:
            return islice(iter(items), max(0, len(items) - n), None)

def _find_c_no_comb(n, k, x):
    """Given x and k, find the largest c such that comb(c, k) <= x.
    This is used for unranking combinations.
    """
    if k == 0:
        return 0
    if x == 0:
        return k - 1
    if k == 1:
        return x
    # Use binary search to find c
    low = k
    high = x + 2
    found = False
    while low < high:
        mid = (low + high) // 2
        c = _combinatorial_choose(mid, k)
        if c <= x:
            low = mid + 1
        else:
            high = mid
            # Check if we found c-1 too
            if c > x and _combinatorial_choose(high - 1, k) <= x:
                return high - 1
    # Final check
    if _combinatorial_choose(high - 1, k) <= x == False:
        return high - 1
    return high - 1

def _uncomb(iterable, k, r, index_last):
    """Unrank to find the r-combination at position index_last.
    Returns the indices relative to sorted iterable.
    """
    positions = []
    for k_pos in range(r, 0, -1):
        c = _find_c_no_comb(len(iterable), k_pos, index_last)
        positions.append(c)
        index_last -= _combinatorial_choose(c, k_pos)
    return positions

def _combinatorial_small(n, k):
    """Compute C(n, k) for small numbers."""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result
from decimal import Decimal
def _combinatorial_big(n, k):
    """Compute C(n, k) with arbitrary precision."""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k
    result = 1
    for i in range(k):
        result = Decimal(result) * (n - i) / Decimal(i + 1)
    return int(result)
def _combinatorial_choose(n, k):
    """Compute C(n, k) with appropriate precision."""
    n = int(n)
    k = int(k)
    max_n = 1000000
    if n > max_n:
        return _combinatorial_big(n, k)
    return _combinatorial_small(n, k)

def nth_combination(iterable, r, index):
    """Equivalent to ``list(combinations(iterable, r))[index]``.

    The subsequences of *iterable* that are of length *r* can be ordered
    lexicographically. :func:`nth_combination` computes the subsequence at
    sort position *index* directly, without computing the previous
    subsequences.

        >>> nth_combination(range(5), 3, 5)
        (0, 3, 4)

    ``ValueError`` will be raised If *r* is negative.
    ``IndexError`` will be raised if the given *index* is invalid.
    """
    if r < 0:
        raise ValueError('r must be non-negative')
    # Try to get the length
    try:
        n = len(iterable)
    except TypeError:
        n = None
    else:
        if r > n:
            raise ValueError('r must be <= len(iterable)')
    # Find the n-th combination
    if isinstance(index, int) and n is not None:
        if index >= _combinatorial_choose(n, r):
            raise IndexError('index out of range')
    positions = []
    for k_pos in range(r, 0, -1):
        c = _find_c_no_comb(n if n is not None else float('inf'), k_pos, index)
        positions.append(c)
        index -= _combinatorial_choose(c, k_pos)
    return tuple([iterable[i] if i < len(iterable) else iterable for i in sorted(positions)])
def _find_c_satisfies_cond(n, k, x):
    """Binary search to find largest c such that comb(c, k) <= x."""
    if k == 0:
        return x
    if k == 1:
        return min(n, x)
    low = k
    high = min(n, int(pow(2, 64)) if n > 1000000 else x + 1)
    if high < k:
        return k - 1
    # Binary search
    while low < high:
        mid = (low + high) // 2
        c_mid = _combinatorial_choose(mid, k)
        if c_mid <= x:
            low = mid + 1
        else:
            high = mid
    return low - 1

def next_version(self, part: str, prerelease_token: str = "rc") -> "Version":
    """
    Determines next version, preserving natural order.

    .. versionadded:: 2.10.0

    This function is taking prereleases into account.
    The "major", "minor", and "patch" raises the respective parts like
    the ``bump_*`` functions. The real difference is using the
    "prerelease" part. It gives you the next patch version of the
    prerelease, for example:

    >>> str(semver.Version.parse("0.1.4").next_version("prerelease"))
    '0.1.5-rc.1'

    :param part: One of "major", "minor", "patch", or "prerelease"
    :param prerelease_token: prefix string of prerelease, defaults to 'rc'
    :return: new object with the appropriate part raised
    """
    cls = type(self)
    if part not in ("major", "minor", "patch", "prerelease"):
        raise ValueError(f"part must be one of 'major', 'minor', 'patch', or 'prerelease', not {part!r}")

    if part == "major":
        # Bumping major always resets minor, patch, and prerelease
        return cls(self.major + 1)
    elif part == "minor":
        # If there's a prerelease, bump minor but keep prerelease
        if self._prerelease:
            return cls(self.major, self.minor + 1, self._prerelease, self._build)
        # Otherwise use bump_minor
        return self.bump_minor()
    elif part == "patch":
        # If there's a prerelease, strip it and bump patch
        if self._prerelease:
            return cls(self.major, self.minor, self._patch + 1)
        # Otherwise use bump_patch
        return self.bump_patch()
    elif part == "prerelease":
        if self._prerelease:
            # Increment the prerelease number
            prerelease = cls._increment_prerelease(self._prerelease)
            return cls(self.major, self.minor, self._patch, prerelease, self._build)
        else:
            # No prerelease, bump patch and add prerelease
            patch = self._patch
            if prerelease_token == "":
                prerelease = "1"
            elif prerelease_token is None:
                prerelease = "rc.1"
            else:
                prerelease = str(prerelease_token) + ".1"
            return cls(self.major, self.minor, patch + 1, prerelease, self._build)
    else:
        raise ValueError(f"part must be one of 'major', 'minor', 'patch', or 'prerelease', not {part!r}")

