@contextmanager
def raises(
    exc, msg: typing.Optional[str] = None, regex: typing.Optional[re.Pattern] = None
) -> Generator[None, None, None]:
    """Context manager for testing that an exception is raised.

    Usage examples:

        >>> with raises(Invalid, 'error message'):
        ...   schema({'bad': 'value'})
        >>> with raises(Invalid):
        ...   schema({'bad': 'value'})

    :param exc: The exception class to expect (or an instance with custom repr)
    :param msg: Optional message to compare with exception message
    :param regex: Optional regex to match exception message
    """
    try:
        yield
    except exc as e:
        if isinstance(exc, Exception):
            # exc is an instance, check if it's the same or in the message
            if str(exc) not in str(e):
                raise AssertionError(
                    f"Expected '{str(exc)}' in exception message, got '{str(e)}'"
                )
            return
        if msg is not None:
            if str(e) != msg:
                raise AssertionError(
                    f"Expected message to be '{msg}', got '{str(e)}'"
                )
        if regex is not None and regex.search(str(e)) is None:
            raise AssertionError(
                f"Expected message to match regex {regex!r}, got '{str(e)}'"
            )
        return
    raise AssertionError(f"No {exc.__name__} raised")

