@classmethod
def infer(cls, data, **kwargs) -> Schema:
    """Create a Schema from concrete data (e.g. an API response).

    For example, this will take a dict like:

    {
        'foo': 1,
        'bar': {
            'a': True,
            'b': False
        },
        'baz': ['purple', 'monkey', 'dishwasher']
    }

    And return a Schema:

    {
        'foo': int,
        'bar': {
            'a': bool,
            'b': bool
        },
        'baz': [str]
    }

    Note: only very basic inference is supported.
    """
    required = kwargs.get('required', False)
    extra = kwargs.get('extra', PREVENT_EXTRA)

    if isinstance(data, Schema):
        data = data.schema

    if isinstance(data, dict):
        schema = {}
        for key, value in data.items():
            key_type = key
            if isinstance(key, Marker):
                key_type = key.schema
            inferred_value = cls._infer_value(type(value), value)
            key_normalized = key_type if is_primitive_type(type(key)) else type(key)
            if isinstance(key, Marker):
                key_normalized = key
            schema[key_normalized] = inferred_value
        schema = cls(schema, required=required, extra=extra)
    elif isinstance(data, (list, tuple)):
        inferred_types = [cls._infer_value(type(value), value) for value in data]
        schema = cls(list(inferred_types), required=required, extra=extra)
    else:
        inferred_type = cls._infer_value(type(data), data)
        schema = cls(inferred_type, required=required, extra=extra)
    return schema

@classmethod
def _infer_value(cls, type_, value):
    """Infer the schema type for a value."""
    # For list/tuple, infer the types of elements (since empty list/tuple should be list/tuple)
    if isinstance(type_, (list, tuple)):
        if not type_:
            return list
        types = cls._infer_types([value])
        return [t for t, _ in types]
    if isinstance(type_, dict):
        if not type_:
            return dict
        return {
            cls._infer_key(key): cls._infer_value_type(value) 
            for key, value in type_.items()
        }
    # Value is not empty or is empty without dict/list
    if type_ in (list, tuple):
