def inverse(self) -> BidictBase[VT, KT]:
    """The inverse of this bidirectional mapping instance."""
    # First check if a strong reference is already stored.
    if self._inv is not None:
        return self._inv
    # Compute the inverse on first access.
    inv = self._make_inverse()
    # Store a strong reference to the inverse, and a weak reference back to self.
    self._inv = inv
    inv._invweak = weakref.ref(self)
    return inv

