            if '*' in str(path[-1]) if path else False:
                if isinstance(value, MutableMapping):
                    walk(value, list(split_glob), path + ([key] if not str(path[-1]).startswith('*') else path[-1]))
                elif isinstance(value, MutableSequence) and len(value) > 0:
                    # For sequence elements
                    if isinstance(current_path_tokens[-1], int):
                        walk(value, list(split_glob), (*current_path_tokens[:-1], len(current_path_tokens) if current_path_tokens else 0))
                    else:
                        walk(value, list(split_glob), path + ([key, str(len(current_path_tokens) if current_path_tokens else 0)]))
