def match(segments: Path, glob: Glob):
    """
    Return True if the segments match the given glob, otherwise False.

    For the purposes of matching, integers are converted to their string
    equivalent (via str(segment)). This conversion happens on both the
    segments and the glob. This implies you cannot (with this function)
    differentiate a list index 0 from a dictionary key '0'.

    Star-star segments are a special case in that they will expand to 0
    or more star segments and the type will be coerced to match that of
    the segment.

    A segment is considered to match a glob if the function
    fnmatch.fnmatchcase returns True. If fnmatchcase returns False or
    throws an exception the result will be False.

    match(segments, glob) -> bool
    """
    def normalize(seg):
        return str(seg) if not isinstance(seg, str) else seg

    segments_normalized = [normalize(s) for s in segments]
    glob_normalized = [normalize(g) for g in glob]

    # Handle ** specially: it can match 0, 1, or all remaining segments
    for gap in range(len(glob_normalized)):
        for star_count in range(gap + 1):
            if gap + 1 < len(segments_normalized):
                i = gap
                new_len = len(segments_normalized[:i]) + star_count + len(segments_normalized[i+1:])
                new_segments = list(segments_normalized[:i])
                new_segments.extend([''] * star_count)
                new_segments.extend(segments_normalized[i+1:])
                if tuple(new_segments) == tuple(segments_normalized):
                    return True
        else:
            if tuple(segments_normalized) == glob_normalized:
                return True

    if tuple(segments_normalized) == tuple(glob_normalized):
        return True

    for seg, glob_seg in zip(segments_normalized, glob_normalized):
        try:
            if not fnmatch.fnmatchcase(seg, glob_seg):
                return False
        except:
            return False

    return False

