def raises(
    exc, msg: typing.Optional[str] = None, regex: typing.Optional[re.Pattern] = None
) -> Generator[None, None, None]:
    """
    Context manager for testing that an exception is raised.

    Usage:
        with raises(Invalid):
            schema('invalid')

        with raises(Invalid, 'expected message'):
            schema('invalid')

        with raises(Invalid, compiled_pattern):
            schema('invalid')
    """
    try:
        yield
        raise AssertionError("No exception raised (expected {})".format(exc.__name__))
    except exc as e:
        if msg is not None:
            if isinstance(regex, re.Pattern):
                if not regex.search(str(e)):
                    raise AssertionError(
                        "Exception message does not match {}.pattern: {}".format(regex.pattern, e)
