        prefix_glob = glob[:glob_idx]
        suffix_glob = glob[glob_idx + 1:]

        # Check prefix matches
        for seg, glob_seg in zip(prefix_segments, prefix_glob):
            try:
                if not fnmatchcase(seg, glob_seg):
                    return False
            except Exception:
                return False
        # Check suffix matches
        for seg, glob_seg in zip(suffix_segments, suffix_glob):
            try:
                if not fnmatchcase(seg, glob_seg):
                    return False
            except Exception:
                return False
        return True

