def next_version(self, part: str, prerelease_token: str = "rc") -> "Version":
    """
    Determines next version, preserving natural order.

    .. versionadded:: 2.10.0

    This function is taking prereleases into account.
    The "major", "minor", and "patch" raises the respective parts like
    the ``bump_*`` functions. The real difference is using the
    "prerelease" part. It gives you the next patch version of the
    prerelease, for example:

    >>> str(semver.Version.parse("0.1.4").next_version("prerelease"))
    '0.1.5-rc.1'

    :param part: One of "major", "minor", "patch", or "prerelease"
    :param prerelease_token: prefix string of prerelease, defaults to 'rc'
    :return: new object with the appropriate part raised
    """
    if part not in ("major", "minor", "patch", "prerelease"):
        raise ValueError(f"part {part!r} is not valid")

    cls = type(self)
    version = self.to_tuple()
    major, minor, patch = version[:3]
    prerelease = version[3]

    if part == "prerelease":
        if prerelease is None:
            return cls(major, minor, patch, prerelease_token + ".1")
        else:
            return cls(major, minor, patch, cls._increment_prerelease(prerelease))

    # For major, minor, patch: prerelease versions become release versions
    if prerelease:
        if part == "major":
            if major == 1 and minor == 0 and patch == 0:
                return cls(major, minor, patch)
            return cls(major + 1, 0, 0)
        elif part == "minor":
            if minor == 0 and major == 0 and patch == 0:
                return cls(major, minor, patch)
            return cls(major, minor + 1, 0)
        elif part == "patch":
            return cls(major, minor, patch)

    # No prerelease - just bump the version part
    elif prerelease is None:
        if part == "major":
            return cls(major + 1, 0, 0)
        elif part == "minor":
            return cls(major, minor + 1, 0)
        else:
            return cls(major, minor, patch + 1)

