@staticmethod
def _infer_type(value):
    """Infer the schema type from a Python value."""
    if value is None:
        return type(None)
    elif isinstance(value, bool):
        return bool
    elif isinstance(value, int):
        return int
    elif isinstance(value, float):
        return float
    elif isinstance(value, str):
        return str
    elif isinstance(value, dict):
        return dict
    elif isinstance(value, (list, tuple, frozenset, set)):
        return list
    else:
        # For nested dicts, we need to infer the inner type
        if isinstance(value, dict):
            if not value:
                return dict
            # Get the first key-value pair to infer the value type
            first_key = next(iter(value.keys()))
            return Self()  # type will be inferred when called
        else:
            return type(value)

@classmethod
def _infer_dict(cls, data):
    """Infer a schema for a nested dict."""
    if not data:
        return dict
    # For dict values, recursively build a schema with Required markers
    schema = {}
    for key, value in data.items():
        if isinstance(value, dict):
            schema[key] = cls._infer_dict(value)
        elif isinstance(value, list):
            if not value:
                schema[key] = list
            else:
                schema[key] = [cls._infer_type(item) for item in value]
        elif isinstance(value, (str, int, float, bool, type(None))):
            schema[key] = cls._infer_type(value)
        else:
            schema[key] = cls._infer_type(value)
    return schema

