def validate(*a, **kw) -> typing.Callable:
    """Decorator for validating arguments of a function against a given schema.

    Set restrictions for arguments:

        >>> @validate(arg1=int, arg2=int)
        ... def foo(arg1, arg2):
        ...   return arg1 * arg2

    Set restriction for returned value:

        >>> @validate(arg=int, __return__=int)
        ... def bar(arg1):
        ...   return arg1 * 2

    """
    import inspect

    all_arg_schemas = list(a)
    arg_schemas = kw.copy()
    __return__ = arg_schemas.pop('__return__', None)

    def _make_validator(schema):
        """Create a validator that checks value is an instance of the type."""
        if inspect.isclass(schema):
            def type_validator(obj, path):
                if not isinstance(obj, schema):
                    raise er.TypeInvalid('expected %s' % schema.__name__, path)
                return obj
            return type_validator
        elif callable(schema):
            # For callables, wrap in a Schema to validate properly
            inner_schema = Schema(schema)
            def callable_validator(obj, path):
                try:
                    result = schema(obj)
                except ValueError:
                    raise er.ValueInvalid('not a valid value', path)
                except er.Invalid as e:
                    e.prepend(path)
                    raise
                return result
            return callable_validator
        else:
            # Literal value
            def literal_validator(obj, path):
                if obj != schema:
                    raise er.ScalarInvalid('not a valid value', path)
                return obj
            return literal_validator

    def decorator(func):
        def wrapper(*args, **kwargs):
            sig = inspect.signature(func)

            # Build mapping from parameter name to schema
            param_schema_map = {}
            pos = 0

            for param_name, param in sig.parameters.items():
                if param_name in ('self', 'cls'):
                    continue
                if pos < len(all_arg_schemas):
                    param_schema_map[param_name] = _make_validator(all_arg_schemas[pos])
                    pos += 1
                elif param_name in arg_schemas:
                    param_schema_map[param_name] = _make_validator(arg_schemas[param_name])

            # Validate arguments
            bound = sig.bind(*args, **kwargs)
            bound.apply_defaults()

            for param_name, value in bound.arguments.items():
                if param_name in ('self', 'cls'):
                    continue

                schema_validator = param_schema_map.get(param_name)
                if schema_validator is not None:
                    try:
                        schema_validator(value, [func.__name__] + [param_name])
                    except Exception as e:
                        raise er.Invalid(str(e), [func.__name__] + [param_name]) from e

            # Validate return type
            result = func(*args, **kwargs)
            if __return__ is not None:
                return_validator = _make_validator(__return__)
                try:
                    return_validator(result, [func.__name__])
                except Exception as e:
                    raise er.Invalid(str(e), [func.__name__]) from e

            return result

        return wrapper

    return decorator

def extend(
    self,
    schema: Schemable,
    required: typing.Optional[bool] = None,
    extra: typing.Optional[int] = None,
) -> typing.Union[Schema, "Schema"]:
    """Create a new `Schema` by merging this and the provided `schema`.

    Neither this `Schema` nor the provided `schema` are modified. The
    resulting `Schema` inherits the `required` and `extra` parameters of
    this, unless overridden.

    Both schemas must be dictionary-based.

    :param schema: dictionary, or Schema wrapping a dictionary, to extend
        this `Schema` with
    :param required: if set, overrides `required` of this `Schema`
    :param extra: if set, overrides `extra` of this `Schema`
    """
    new_type: typing.Any = type(self)
    if isinstance(schema, Schema):
        if not isinstance(schema.schema, dict):
            raise AssertionError(
                "Both schemas must be dictionary-based" 
            )

        # Check if extra settings can be preserved
        base_extra: int = self.extra
        ext_extra: int = schema.extra
        if base_extra != ext_extra:
            if base_extra == ALLOW_EXTRA and ext_extra != ALLOW_EXTRA:
                raise er.SchemaError(
                    "cannot preserve extra setting" 
                )

        new_type = type(schema)
        self_required: bool = self.required
        self_extra: int = self.extra
        extension_required: bool = schema.required
        extension_extra: int = schema.extra
    else:
        # schema is a dict
        self_required: bool = self.required
        self_extra: int = self.extra
        extension_required: bool = None
        extension_extra: int = None

    self_schema = self._normalize_schema_extension(
        self.schema, self_required, self_extra
    )

    if isinstance(schema, Schema):
        ext_schema = schema._normalize_schema_extension(
            schema.schema, extension_required, self_required
        )
    else:
        ext_schema = schema
        if extension_required is not None:
            ext_schema = ext_schema
        # For dict schemas without required marker, use base's required setting
        # but don't change markers in the dict (those are already normalized)
        if extension_required is not None:
            # Normalize new keys based on extension_required
            ext_schema_normalized: typing.Any = {}
            for key, value in ext_schema.items():
                if key is not Extra and not isinstance(key, Marker):
                    if extension_required:
                        ext_schema_normalized[key] = Required(key)
                    elif self_required:
                        ext_schema_normalized[key] = Optional(key)
                else:
                    ext_schema_normalized[key] = value
            ext_schema = ext_schema_normalized

    result_schema: typing.Any = {}
    for key, value in self_schema.items():
        if key in ext_schema:
            result_schema[key] = ext_schema[key]
        else:
            result_schema[key] = value
    for key, value in ext_schema.items():
        if key not in result_schema:
            result_schema[key] = value

    result = new_type(
        result_schema, 
        required=required if required is not None else self_required, 
        extra=extra if extra is not None else self_extra
    )
    return result
